WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE TRUE),
mk_counts AS MATERIALIZED (SELECT mk.movie_id, COUNT(*)::HUGEINT AS n FROM movie_keyword mk JOIN selected_titles eligible ON eligible.id=mk.movie_id WHERE mk.keyword_id=29360 GROUP BY mk.movie_id)
SELECT COALESCE(SUM(mk.n),0) FROM selected_titles t JOIN mk_counts mk ON mk.movie_id=t.id;

WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE TRUE),
ci_counts AS MATERIALIZED (SELECT ci.movie_id, COUNT(*)::HUGEINT AS n FROM cast_info ci JOIN selected_titles eligible ON eligible.id=ci.movie_id WHERE TRUE GROUP BY ci.movie_id)
SELECT COALESCE(SUM(ci.n),0) FROM selected_titles t JOIN ci_counts ci ON ci.movie_id=t.id;
